import{_ as n,C as r,o as s,c as d,a2 as t,E as a}from"./chunks/framework.CGSzHL4z.js";const w=JSON.parse('{"title":"Colours, gradients and sequences","description":"","frontmatter":{},"headers":[],"relativePath":"features/colors-and-sequences.md","filePath":"features/colors-and-sequences.md","lastUpdated":1792713747000}'),i={name:"features/colors-and-sequences.md"};function h(l,e,c,p,u,g){const o=r("Screenshot");return s(),d("div",null,[e[0]||(e[0]=t('<h1 id="colours-gradients-and-sequences" tabindex="-1">Colours, gradients and sequences <a class="header-anchor" href="#colours-gradients-and-sequences" aria-label="Permalink to &quot;Colours, gradients and sequences&quot;">​</a></h1><p>Particles, beams, trails and lights take colours and sequences, and AcesMotion edits each of them in its own window. The <strong>colour picker</strong> sets a Color3, the <strong>gradient editor</strong> a ColorSequence and the <strong>sequence editor</strong> a NumberSequence. Each window shows its change on the model as you work and keys it when you press OK, so you can shape a fire&#39;s colour ramp or a spark&#39;s size over its life and animate it.</p><h2 id="opening-a-window" tabindex="-1">Opening a window <a class="header-anchor" href="#opening-a-window" aria-label="Permalink to &quot;Opening a window&quot;">​</a></h2><p>Click a Color3 swatch, or a NumberSequence or ColorSequence preview, in the <a href="./inspector">Inspector</a>. The window&#39;s title names the property (&quot;AcesMotion · SlashEmitter.Color&quot;).</p><p>You get one window per property, and you can keep several open at once, up to 6 of each kind. Clicking the same property again leaves its open window as it is.</p><p>Every window has the same footer:</p><table tabindex="0"><thead><tr><th>Control</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Undo</strong>, <strong>Redo</strong></td><td>Step through this window&#39;s own changes (<code>Ctrl+Z</code>, <code>Ctrl+Y</code> work too)</td></tr><tr><td><strong>Cancel</strong></td><td>Puts back the value from before the window opened (<code>Esc</code>, or Studio&#39;s close button)</td></tr><tr><td><strong>OK</strong></td><td>Keeps it: keyed at the playhead with Auto-key on, one undo step (<code>Enter</code>)</td></tr></tbody></table><p>A window also closes as Cancel when its object is gone, the scene closes, or the plugin unloads.</p><h2 id="colour-picker" tabindex="-1">Colour picker <a class="header-anchor" href="#colour-picker" aria-label="Permalink to &quot;Colour picker&quot;">​</a></h2>',9)),a(o,{name:"feat-color",caption:"The colour picker: the hue ring around the saturation and value square, the before and after swatches, hex and RGB fields, and the Saved strip. The pointer drags the hue knob around the ring."}),e[1]||(e[1]=t('<p>Drag on the <strong>hue ring</strong> to set the hue and inside the <strong>square</strong> to set saturation and brightness. The <strong>Old</strong> and <strong>New</strong> swatches compare the colour you started with to the current one; click Old to go back. Type a 6-digit hex (with or without <code>#</code>) or set <strong>R</strong>, <strong>G</strong> and <strong>B</strong> from 0 to 255. Pressing <code>Enter</code> in a field keeps the value and leaves the window open; <code>Enter</code> again is OK.</p><p>The colour picker also opens from a marker&#39;s colour, a block&#39;s Color3 parameter and the accent and bone colours in Settings.</p><h2 id="gradient-editor" tabindex="-1">Gradient editor <a class="header-anchor" href="#gradient-editor" aria-label="Permalink to &quot;Gradient editor&quot;">​</a></h2>',3)),a(o,{name:"feat-gradient",caption:"The gradient editor on Sparks.Color with Blend set to OKLab and 4 of 20 stops. Dragging a stop re-blends the bar."}),e[2]||(e[2]=t('<p>A ColorSequence is a bar with stops under it.</p><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Add a stop</td><td>Click the bar (it takes the colour already there), or press <strong>Add stop</strong> for one halfway to the next</td></tr><tr><td>Move a stop</td><td>Drag it along the bar (the end stops stay at 0 and 1)</td></tr><tr><td>Remove a stop</td><td>Right click it, or select it and press <code>Del</code> (a gradient keeps at least 2)</td></tr><tr><td>Change a stop&#39;s colour</td><td>Double click it to open its own colour picker</td></tr></tbody></table><p>A stop&#39;s colour picker previews into the gradient as you drag. Its OK keeps the colour and its Cancel puts the stop back. The fields under the bar set the selected stop&#39;s <strong>Time</strong> and colour.</p><h3 id="blend" tabindex="-1">Blend <a class="header-anchor" href="#blend" aria-label="Permalink to &quot;Blend&quot;">​</a></h3><p>The <strong>Blend</strong> dropdown in the header picks how colours mix between your stops:</p><table tabindex="0"><thead><tr><th>Blend</th><th>Result</th></tr></thead><tbody><tr><td><strong>OKLab</strong></td><td>Even, natural steps between stops</td></tr><tr><td><strong>OKLCH</strong></td><td>Turns the hue round the colour wheel and keeps colours vivid</td></tr><tr><td><strong>RGB</strong></td><td>Roblox&#39;s plain mix</td></tr></tbody></table><p>Roblox draws a gradient as straight lines between its stops. For OKLab and OKLCH, AcesMotion adds stops in between (20 in all) and keeps them up to date as you edit. The editor only shows your own stops, while the bar shows the whole gradient the way games draw it. When you reopen the gradient, the editor finds its added stops again and picks the blend. A gradient with none opens with <strong>Settings &gt; Timeline &gt; Colour blend</strong>, the same setting that decides how a new colour track goes from key to key.</p><h2 id="sequence-editor" tabindex="-1">Sequence editor <a class="header-anchor" href="#sequence-editor" aria-label="Permalink to &quot;Sequence editor&quot;">​</a></h2>',8)),a(o,{name:"feat-sequence",caption:"The sequence editor on Sparks.Size: 4 of 20 points, Presets, Range min and max, the Time, Value and Envelope fields, and the Saved strip. The pointer drags a point."}),e[3]||(e[3]=t('<p>The canvas shows a grid, the curve, its points and the envelope band. The two end points are squares pinned at time 0 and 1; they move up and down only.</p><table tabindex="0"><thead><tr><th>To</th><th>Do</th></tr></thead><tbody><tr><td>Add a point</td><td>Click the graph and keep dragging; near the line it lands on the line</td></tr><tr><td>Move a point</td><td>Drag it (<code>Shift</code> snaps time to 0.05)</td></tr><tr><td>Remove a point</td><td>Right click it, or press <code>Del</code> or <code>Backspace</code></td></tr><tr><td>Change the random spread</td><td>Select a point and drag the envelope bars above and below it</td></tr></tbody></table><p>The header shows the point count (&quot;4 of 20 points&quot;), the <strong>Range</strong> Min and Max, and a <strong>Fit</strong> button, which sets Min and Max to just hold every point and its envelope, with a little room, rounded to tidy numbers. Fields for the selected point set <strong>Time</strong> (0 to 1), <strong>Value</strong> and <strong>Envelope</strong>. Values are never clamped: typing one outside the range grows it. A sequence holds 20 points at most.</p><p>While a sequence editor is open, applying an ease in the Library&#39;s Easing tab lays it on the selected segment as up to 8 new points.</p><h2 id="presets-and-the-saved-strip" tabindex="-1">Presets and the Saved strip <a class="header-anchor" href="#presets-and-the-saved-strip" aria-label="Permalink to &quot;Presets and the Saved strip&quot;">​</a></h2><p>The <strong>Presets</strong> button opens a menu of thumbnails.</p><table tabindex="0"><thead><tr><th>Editor</th><th>Presets</th></tr></thead><tbody><tr><td>Sequence</td><td>Basic (Constant, Rise, Fall, Ease in, Ease out, Smooth, Hump, Dip), Particles (Pop in, Grow and fade, Shrink out, Burst, Flicker, Puff, Sparkle), UI (Fade left, Fade right, Fade both edges, Shine band, Soft edge)</td></tr><tr><td>Gradient</td><td>Ramps (White to black, Black to white, Red to yellow, Blue to cyan), Looks (Fire, Ice, Rainbow, Sunset)</td></tr></tbody></table><p>Sequence presets are laid on the current Range. Gradient presets replace every stop.</p><p>The <strong>Saved strip</strong> under the fields keeps colours, gradients and sequences in the scene, shared by every window of that kind. <strong>+</strong> saves the current value, a click applies a saved one, and a right click renames or deletes it. A scene holds up to 64 colours, 32 gradients and 32 sequences. The <strong>...</strong> beside <strong>+</strong> exports and imports them as preset files.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>In the Inspector, a sequence row has a one-value control before its preview. Type one number, or pick one colour, to make the whole sequence that value.</li><li>Sparkle rolls new envelopes each time you apply it.</li><li>A generator can drive a colour along a gradient, or morph between two sequences, and edits them in these same windows (see <a href="./generators#drive-modes">Generators</a>).</li></ul><h2 id="compared-to-roblox-s-animation-editor" tabindex="-1">Compared to Roblox&#39;s Animation Editor <a class="header-anchor" href="#compared-to-roblox-s-animation-editor" aria-label="Permalink to &quot;Compared to Roblox&#39;s Animation Editor&quot;">​</a></h2><p>Roblox&#39;s Animation Editor animates joints and faces, so it has no colour, gradient or sequence editors. Studio&#39;s Properties window does edit ColorSequence and NumberSequence values, but those edits aren&#39;t keyed. In AcesMotion a gradient or sequence is a track like any other: key it at different frames and the scene plays the change.</p>',13))])}const m=n(i,[["render",h]]);export{w as __pageData,m as default};
